import React, { useState } from 'react';

// Import 4 màn hình con từ thư mục components
import MovieList from './components/MovieList';
import ShowtimeScreen from './components/ShowtimeScreen';
import SeatScreen from './components/SeatScreen';
import AuthScreen from './components/AuthScreen';
import defaultDatabase from './data/database';

function App() {
  const movies = defaultDatabase.movies;
  const showtimes = defaultDatabase.showtimes;
  const seats = defaultDatabase.seats;
  const [bookings, setBookings] = useState(defaultDatabase.bookings);

  const [currentScreen, setCurrentScreen] = useState('movie-list');
  const [selectedMovie, setSelectedMovie] = useState(null);
  const [selectedShowtime, setSelectedShowtime] = useState(null);

  return (
    <div style={{ backgroundColor: '#e6f7ff', minHeight: '100vh', paddingBottom: '40px' }}>
      <nav className="navbar navbar-expand-lg custom-navbar shadow-sm">
        <div className="container">
          <span
            className="navbar-brand mb-0 h1 fw-bold text-white fs-3"
            style={{ cursor: 'pointer', letterSpacing: '1px' }}
            onClick={() => setCurrentScreen('movie-list')}
          >
            🎬 BETA CINEMA
          </span>
          {selectedMovie && currentScreen !== 'movie-list' && (
            <span className="text-white-50 d-none d-sm-inline">
              Phim đang chọn: <strong className="text-white">{selectedMovie.title}</strong>
            </span>
          )}
        </div>
      </nav>

      {/* ĐIỀU HƯỚNG MÀN HÌNH */}
      <div className="container">
        {currentScreen === 'movie-list' && (
          <MovieList 
            movies={movies} 
            showtimes={showtimes}
            onSelectMovie={(movie) => { 
              setSelectedMovie(movie); 
              setCurrentScreen('showtime-list'); 
            }}
            onGoToAuth={() => setCurrentScreen('auth')}
          />
        )}

        {currentScreen === 'showtime-list' && (
          <ShowtimeScreen 
            movie={selectedMovie} 
            showtimes={showtimes} 
            onSelectShowtime={(st) => { 
              setSelectedShowtime(st); 
              setCurrentScreen('seat-plan'); 
            }}
            onBack={() => setCurrentScreen('movie-list')} 
          />
        )}

        {currentScreen === 'seat-plan' && (
          <SeatScreen 
            showtime={selectedShowtime} 
            movie={selectedMovie}
            seats={seats}
            bookings={bookings}
            onBookingSuccess={(newBookings) => setBookings([...bookings, ...newBookings])}
            onBack={() => setCurrentScreen('showtime-list')}
          />
        )}

        {currentScreen === 'auth' && (
          <AuthScreen onBack={() => setCurrentScreen('movie-list')} />
        )}
      </div>
    </div>
  );
}

export default App;
